function applyAppearance(){
  const choice=['light','dark','auto'].includes(prefs.theme)?prefs.theme:'auto';
  const solar=state.data?.solar?.state;
  const resolved=choice==='auto'?(solar==='above_horizon'?'light':solar==='below_horizon'?'dark':matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):choice;
  document.documentElement.dataset.theme=resolved;
  const background=['weather','soft','plain','photos'].includes(prefs.background)?prefs.background:'weather';
  document.documentElement.dataset.background=background;
  document.body.classList.toggle('has-photos',background==='photos'&&state.photos.length>0);
  if($('#appearance-button'))$('#appearance-button').title=`Vzhled: ${choice==='auto'?'Automaticky':resolved==='light'?'Světlý':'Tmavý'}`;
  updateWeatherBackground();configureNavigationSound();
}
function appearanceDialog(){
  const selected=prefs.theme||'auto',background=prefs.background||'weather';
  showDialog('Vzhled a pozadí',`<p>Vyber si vzhled televize. Automatický režim používá východ a západ slunce z HA Domov.</p><div class="appearance-options" aria-label="Barevný režim">${[['light','Světlý','sun'],['dark','Tmavý','moon'],['auto','Automaticky','spark']].map(([id,label,glyph])=>`<button class="appearance-option ${selected===id?'selected':''}" data-theme-choice="${id}" aria-pressed="${selected===id}">${icon(glyph)}<strong>${label}</strong></button>`).join('')}</div><div class="settings-section"><h3>Pozadí</h3><div class="background-options">${[['weather','Počasí a slunce'],['plain','Jednobarevné'],['photos','Naše fotografie']].map(([id,label])=>`<button class="background-option ${background===id?'selected':''}" data-background-choice="${id}" aria-pressed="${background===id}"><span class="background-swatch ${id}">${id==='photos'?icon('photo'):''}</span><strong>${label}</strong></button>`).join('')}</div><p class="photo-status">${state.photos.length?`${state.photos.length} fotografií v knihovně`:'Vlastní fotografie zatím nejsou přidané.'}</p>${state.bootstrap?.preview?.readOnly?'<p class="description">Živý náhled používá domácí knihovnu. Úpravy fotografií jsou tu vypnuté.</p>':isTv?'<p class="description">Fotografie přidej v tomto rozhraní na počítači nebo telefonu. Na TV se potom objeví ve společné knihovně.</p>':'<label class="small-button photo-upload-label" for="background-upload">Přidat vlastní fotografii</label><input id="background-upload" class="photo-file-input" type="file" accept="image/jpeg,image/png,image/webp"><p id="background-upload-status" class="photo-status">JPG, PNG nebo WebP do 12 MB. Fotografie zůstane v domácí síti.</p>'}</div><p class="photo-status">${selected==='auto'?(state.data?.solar?.state==='above_horizon'?'Podle HA Domov je právě den.':state.data?.solar?.state==='below_horizon'?'Podle HA Domov je po západu slunce.':'Čekám na údaje o slunci z HA.'): 'Volba se ukládá pro tuto obrazovku.'}</p>`);
  $$('[data-theme-choice]').forEach(b=>b.onclick=()=>{prefs.theme=b.dataset.themeChoice;savePrefs();applyAppearance();appearanceDialog();$(`[data-theme-choice="${prefs.theme}"]`)?.focus();});
  $$('[data-background-choice]').forEach(b=>b.onclick=()=>{prefs.background=b.dataset.backgroundChoice;savePrefs();applyAppearance();appearanceDialog();$(`[data-background-choice="${prefs.background}"]`)?.focus();});
  if($('#background-upload'))$('#background-upload').onchange=async e=>{const file=e.target.files?.[0],status=$('#background-upload-status');if(!file)return;if(file.size>12*1024*1024){status.textContent='Fotografie je větší než 12 MB.';return;}status.textContent='Ukládám fotografii…';try{const r=await fetch('/api/photos/upload',{method:'POST',headers:{'Content-Type':file.type},body:file});const answer=await r.json();if(!r.ok)throw Error(answer.error||'Fotografii nelze uložit.');const pr=await fetch('/api/photos');if(!pr.ok)throw Error('Knihovnu nelze načíst.');const photos=await pr.json();state.photos=Array.isArray(photos)?photos:photos.photos||[];prefs.background='photos';savePrefs();state.photo=Math.max(0,state.photos.findIndex(p=>p.id===answer.photo?.id));applyAppearance();nextPhoto();appearanceDialog();}catch(error){if(status.isConnected)status.textContent=error.message;}};
}

const number = (v, unit='', digits=0) => v !== null && v !== undefined && Number.isFinite(Number(v)) ? `${Number(v).toLocaleString('cs-CZ',{maximumFractionDigits:digits})}${unit}` : '—';
const dateFormatters=new Map();
const dayFormat=(d,opts={})=>{const key=JSON.stringify(opts);let formatter=dateFormatters.get(key);if(!formatter){formatter=new Intl.DateTimeFormat('cs-CZ',opts);if(dateFormatters.size>=64)dateFormatters.delete(dateFormatters.keys().next().value);dateFormatters.set(key,formatter);}return formatter.format(d);};
const setText=(selector,value)=>{const element=$(selector);if(element&&element.textContent!==value)element.textContent=value;};
function unavailableData(mode='setup'){return {mode,updatedAt:null,weather:{},calendars:[],cameras:[],mediaPlayers:[],scenes:[],home:{lights:[],locks:[],doors:[],alarm:{state:'unavailable'}},insights:[]};}
function normalize(data){return {weather:{},calendars:[],cameras:[],mediaPlayers:[],scenes:[],home:{lights:[],locks:[],doors:[]},...data,home:{lights:[],locks:[],doors:[],...(data.home||{})}};}
function weatherValue(key){const value=state.data?.weather?.[key];return value&&typeof value==='object' ? value.value ?? value.state : value;}
function weatherMetricMarkup(key,label,glyph,digits=0){const unit=state.data?.weather?.units?.[key];return `<div class="metric">${icon(glyph)}<div><small>${esc(label)}</small><span>${number(weatherValue(key),unit?' '+esc(unit):'',digits)}</span></div></div>`;}
function weatherFeelsLikeMarkup(){const value=weatherValue('feelsLike'),unit=state.data?.weather?.units?.feelsLike;return typeof value==='number'&&Number.isFinite(value)?`<span class="subtle">Pocitově ${number(value,unit?' '+esc(unit):'',1)}</span>`:'';}
function updateClock(){updateWeatherBackground();const d=new Date();const time=dayFormat(d,{hour:'2-digit',minute:'2-digit',second:'2-digit'});setText('#clock',time);setText('#saver-clock',dayFormat(d,{hour:'2-digit',minute:'2-digit'}));setText('#date-label',dayFormat(d,{weekday:'long',day:'numeric',month:'long'}));setText('#saver-date',dayFormat(d,{weekday:'long',day:'numeric',month:'long',year:'numeric'}));const h=d.getHours();setText('#greeting',`${h<5?'Dobrou noc':h<11?'Dobré ráno':h<18?'Dobrý den':'Dobrý večer'}.`);updateDomesticClock();updateNoticeIndicator();}
function calendarsAvailable(){return state.mode==='demo'||(state.mode==='live'&&state.data.calendars.some(c=>c.available!==false));}
function events(){return state.data.calendars.flatMap(c=>(c.events||[]).map(e=>({...e,calendar:c.name}))).sort((a,b)=>Date.parse(a.start?.dateTime||a.start?.date||a.start)-Date.parse(b.start?.dateTime||b.start?.date||b.start));}
const eventStart = e => e.start?.dateTime || e.start?.date || e.start;
function eventTime(e){const v=eventStart(e);return v?.length===10?'Celý den':v&&!Number.isNaN(Date.parse(v))?dayFormat(new Date(v),{hour:'2-digit',minute:'2-digit'}):'—';}
const calendarDayKey = value => {const d=new Date(value);return Number.isNaN(d.valueOf())?'unknown':new Intl.DateTimeFormat('sv-SE',{year:'numeric',month:'2-digit',day:'2-digit'}).format(d);};
function eventMarkup(e,full=false){const key=HomeTVCalendar.dayKey(eventStart(e)),d=key?HomeTVCalendar.dayBounds(key).start:null;const when=!full?`<span class="event-day">${d?esc(dayFormat(d,{weekday:'short',day:'numeric',month:'numeric'})):'Datum neznámé'}</span><small>${esc(eventTime(e))}</small>`:esc(eventTime(e));return `<div class="event"><time${key?` datetime="${key}"`:''}>${when}</time><div><strong>${esc(e.summary||'Událost')}</strong><p>${esc(e.calendar||'Rodina')}</p></div></div>`;}
function calendarAgenda(list){const days=state.calendarDay?[state.calendarDay]:Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i);return HomeTVCalendar.dayKey(d);});const groups=days.map(key=>({key,items:list.filter(e=>HomeTVCalendar.overlapsDay(e,key))})).filter(g=>g.items.length);if(!groups.length)return `<div class="empty-state">${calendarsAvailable()?'Na vybrané dny nemáte žádné události.':'Kalendář není dostupný.'}</div>`;return groups.map(({key,items})=>{const d=HomeTVCalendar.dayBounds(key).start;return `<section class="agenda-day"><h3>${esc(dayFormat(d,{weekday:'long',day:'numeric',month:'long'}))}</h3>${items.map(e=>eventMarkup(e,true)).join('')}</section>`;}).join('');}
function calendarWeek(list){return `<div class="calendar-week" aria-label="Dny kalendáře">${Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+i);const key=calendarDayKey(d),hasEvents=list.some(e=>HomeTVCalendar.overlapsDay(e,key));return `<button class="calendar-day ${state.calendarDay===key?'selected':''} ${i===0?'today':''}" data-calendar-day="${key}" aria-pressed="${state.calendarDay===key}"><span>${esc(dayFormat(d,{weekday:'short'}))}</span><strong>${d.getDate()}</strong><i class="${hasEvents?'has-events':''}"></i></button>`;}).join('')}</div>`;}
function homeSummary(){const home=state.data.home;const all=home.lights||[];const lights=all.filter(l=>l.role!=='controller-status');const on=lights.filter(l=>l.state==='on');const unknownLights=!lights.length||lights.some(l=>!['on','off'].includes(l.state));const controllers=all.filter(l=>l.role==='controller-status');const activeControllers=controllers.filter(l=>l.state==='on');const locks=home.locks||[];const unlocked=locks.filter(l=>l.state==='unlocked');const locked=locks.length&&locks.every(l=>l.state==='locked');const unknownLocks=!locks.length||locks.some(l=>!['locked','unlocked'].includes(l.state));const rooms=[...new Set(on.map(l=>l.area||l.name))];return {on,unknownLights,controllers,activeControllers,locks,unlocked,locked,unknownLocks,rooms};}
function homeStrip(saver=false){const s=homeSummary();let lockLabel=s.unlocked.length?'Odemčeno':s.unknownLocks?'Zámek · stav neznámý':s.locked?'Zamčeno':'Zámek · neověřeno';const lightLabel=s.rooms.length?`Svítí · ${s.rooms.slice(0,2).join(', ')}${s.rooms.length>2?` +${s.rooms.length-2}`:''}`:s.unknownLights?'Světla · neúplný stav':'Vybraná světla zhasnutá';const uncertain=s.unknownLights||s.activeControllers.length;const notice=state.mode==='demo'?'Ukázková oznámení':state.eventsConnected&&state.bootstrap.notifications?.connected?'Oznámení připojena':'Oznámení nepřipojena';return `${saver?`<div class="home-state">${icon('sun')}<span>${number(weatherValue('temperature'),' °C',1)}</span></div>`:`<div class="label">${icon('home')}Stav domu</div>`}<button class="home-state text-button" data-action="house">${icon(s.unlocked.length?'unlock':'lock')}<span class="${s.unlocked.length?'state-warning':s.locked?'state-good':''}">${esc(lockLabel)}</span></button><button class="home-state text-button" data-action="house">${icon('bulb')}<span>${esc(lightLabel)}${!saver&&uncertain?' <small>· část údajů neověřena</small>':''}</span></button><div class="home-state">${icon('bell')}<span>${esc(notice)}</span></div>${!saver?'<button class="text-button" data-domestic-section="security">'+icon('shield')+' Zabezpečení '+'</button><button class="text-button home-kino" data-action="kino" aria-pressed="false">'+icon('play')+' Kino</button><button class="text-button" data-action="night">'+icon('moon')+' Dobrou noc</button>':''}`;}

function cameraCard(c){return `<button class="card glass camera-card" data-camera="${esc(c.id)}" data-overview-camera="${state.tab==='home'?esc(c.id):''}" aria-label="Otevřít kameru ${esc(c.name)}"><div class="camera-preview">${state.tab==='home'&&state.mode==='live'&&c.available?'<video id="overview-camera-video" class="overview-camera-video" muted autoplay playsinline tabindex="-1" aria-hidden="true"></video>':''}${state.mode==='live'&&c.available?`<img src="${cardSnapshots.get(c.id)||`/api/cameras/${encodeURIComponent(c.id)}/snapshot`}" alt="Snímek kamery ${esc(c.name)}" data-camera-image="${esc(c.id)}">`:`<div class="camera-placeholder">${icon('camera')}<span>${state.mode==='demo'?'Místo pro živý pohled':c.available?'Otevřít živý pohled':'Kamera není dostupná'}</span></div>`}<div class="camera-top"><span>${esc(c.name)}</span><span class="status-tag"><i></i>${state.mode==='demo'?'Ukázka':c.available?(state.tab==='home'?'Snímek':'Snímek'):'Nedostupná'}</span></div></div><div class="camera-bottom"><div><strong>${esc(c.name||'Kamera')}</strong><small>${state.mode==='demo'?'Živý obraz se připojí přes HA':'Otevřít kameru'}</small></div><span class="round-arrow">${icon('chevron')}</span></div></button>`;}
const builtinApps=[{id:'media',name:'Média',subtitle:'Filmy, hudba a videa',icon:'play',style:'movies',action:'media'},{id:'cameras',name:'Kamery',subtitle:'Přehled kolem domu',icon:'camera',style:'cameras',action:'cameras'},{id:'calendar',name:'Rodina',subtitle:'Společné plány',icon:'calendar',style:'calendar',action:'calendar'},{id:'relax',name:'Chvíle klidu',subtitle:'Dech a odpočinek',icon:'leaf',style:'relax',url:'/apps/relax/'},{id:'quiz',name:'Rodinný kvíz',subtitle:'Malá hra pro všechny',icon:'spark',style:'quiz',url:'/apps/rodinne-kvizy/'},{id:'add',name:'Tvoje aplikace',subtitle:'Další nápad začíná tady',icon:'plus',style:'more',action:'add-app'}];
function webApps(){const custom=(state.bootstrap.apps||[]).filter(a=>!builtinApps.some(b=>b.url===a.url)).map(a=>({...a,subtitle:a.description||'Vlastní aplikace',style:'more',icon:a.icon||'grid'}));return [...builtinApps,...custom];}
function appsMarkup(items=webApps()){return `<div class="app-grid">${items.map(a=>`<button class="app-item" data-app="${esc(a.id)}"><div class="app-art ${esc(a.style)}">${icon(a.icon)}</div><strong>${esc(a.name)}</strong><small>${esc(a.subtitle)}</small></button>`).join('')}</div>`;}

