try{const cached=JSON.parse(localStorage.getItem('home-tv-apps')||'null');if(cached&&Date.now()-cached.at<7*86400000&&Array.isArray(cached.ids)){const apps=Object.keys(tvAppDesign).filter(id=>cached.ids.includes(id)).map(appId=>({appId}));if(apps.length||!isTv)state.tvApps=apps;}}catch{}
function tvAppsMarkup(limit=Infinity,start=0){return `<div class="app-grid tv-app-grid">${state.tvApps.slice(start,Number.isFinite(limit)?start+limit:undefined).filter(a=>Object.hasOwn(tvAppDesign,a.appId)).map(a=>{const d=tvAppDesign[a.appId],href=isTv&&!state.bootstrap?.preview?.readOnly?nativeTvAppUrl(a.appId):null,tag=href?'a':'button';return `<${tag} class="app-item native-app" ${href?`href="${esc(href)}"`:''} ${state.bootstrap?.preview?.readOnly?'aria-disabled="true"':''} data-tv-app="${esc(a.appId)}" aria-label="Otevřít ${esc(d.name)}"><div class="app-art ${d.style}${d.glyph?' utility-brand':''}">${d.glyph?icon(d.glyph):''}<span class="app-wordmark">${esc(d.mark)}</span></div><strong>${esc(d.name)}</strong></${tag}>`;}).join('')}</div>`;}
function homeAppsMarkup(){return state.tvApps.length?tvAppsMarkup(6):'<div class="native-apps-loading">'+(isTv&&state.nativeAppsReceived?'Vybrané TV aplikace nejsou na této televizi dostupné.':state.bootstrap.authenticated?'Načítám nainstalované TV aplikace…':'Nainstalované aplikace se zobrazí po připojení televize.')+'</div>';}
async function loadTvApps(){if(isTv){if(window.HomeTVNativeApps)applyNativeTvApps(window.HomeTVNativeApps);return;}if(!state.bootstrap.authenticated||(!state.bootstrap.assistant?.tvControl&&!state.bootstrap?.preview?.readOnly))return;try{const r=await fetch('/api/tv/apps');if(!r.ok)return;const result=await r.json();const available=new Map((result.apps||[]).map(a=>[a.appId,a]));state.tvApps=Object.keys(tvAppDesign).filter(id=>available.has(id)).map(id=>available.get(id));try{localStorage.setItem('home-tv-apps',JSON.stringify({at:Date.now(),ids:state.tvApps.map(a=>a.appId)}));}catch{}if(!state.dialog&&!state.saver)render();}catch{}}
function applyNativeTvApps(snapshot){if(!isTv||!snapshot||!Array.isArray(snapshot.appIds)||snapshot.appIds.length>256||snapshot.appIds.some(id=>typeof id!=='string'))return false;const ids=Object.keys(tvAppDesign).filter(id=>snapshot.appIds.includes(id)),changed=ids.join('|')!==state.tvApps.map(app=>app.appId).join('|');state.nativeAppsReceived=true;if(changed&&document.activeElement?.dataset?.tvApp&&!ids.includes(document.activeElement.dataset.tvApp))state.appFocusIntent='first';state.tvApps=ids.map(appId=>({appId}));try{localStorage.setItem('home-tv-apps',JSON.stringify({at:Date.now(),ids}));}catch{}if(!state.dialog&&!state.saver){if(changed)render();else focusTvAppTile();}return true;}
window.addEventListener('tv-native-apps',event=>applyNativeTvApps(event.detail));
if(isTv&&window.HomeTVNativeApps)applyNativeTvApps(window.HomeTVNativeApps);
function nativeTvAppUrl(appId){return typeof appId==='string'&&Object.hasOwn(tvAppDesign,appId)?'hometv://launch?appId='+encodeURIComponent(appId):null;}
function rememberTvAppLaunch(appId){state.lastLaunchedTvApp=appId;state.appReturnPending=true;state.appFocusIntent=null;state.lastInput=Date.now();}
function activateTvApp(event,element){const appId=element.dataset.tvApp,url=nativeTvAppUrl(appId);if(isTv&&!state.bootstrap?.preview?.readOnly){if(url&&state.tvApps.some(a=>a.appId===appId)&&element.tagName==='A'&&element.getAttribute('href')===url){rememberTvAppLaunch(appId);return;}event.preventDefault();return;}event.preventDefault();return launchTvApp(appId);}
function launchTvApp(appId){if(state.bootstrap?.preview?.readOnly)return notify({title:'Živý náhled · pouze čtení',message:'Ovládání televize tu zůstává vypnuté.'});const app=state.tvApps.find(a=>a.appId===appId),url=nativeTvAppUrl(appId);if(!app||!url)return;if(isTv){rememberTvAppLaunch(appId);location.href=url;return;}return launchTvAppFromServer(appId);}
async function launchTvAppFromServer(appId){try{const r=await fetch('/api/tv/launch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({appId})});const answer=await r.json();if(!r.ok||!answer.accepted)throw Error(answer.error||'Aplikaci nelze otevřít.');}catch(error){notify({title:'Aplikaci nelze otevřít',message:error.message,type:'warning'});}}
function renderHome(){const d=new Date();const list=events();return `<div class="dashboard-grid"><article class="card glass weather-card"><div class="card-heading"><div class="label">${icon('sun')}Venku právě teď</div>${weatherFeelsLikeMarkup()}</div><div class="weather-main"><div><div class="temperature">${number(weatherValue('temperature'),' ',1)}<sup>°</sup></div><p class="weather-description">${esc(weatherDescription())}</p><div class="weather-location">${state.mode==='demo'?'Ukázkové hodnoty':state.mode==='live'?(state.data.weather.conditionSource==='weather-provider'?'Podmínky z předpovědi · vlastní měření':'Vlastní měření u domu'):'Hodnoty zatím nejsou dostupné'}</div></div><div class="weather-art" aria-hidden="true"><div class="sun"></div><div class="cloud"></div></div></div><div class="weather-metrics">${[['windSpeed','Vítr','wind',0],['windGust','Nárazy','wind',0],['windDirection','Směr','compass',0],['humidity','Vlhkost','drop',0],['rainRate','Déšť','rain',1],['pressure','Tlak','gauge',0]].map(metric=>weatherMetricMarkup(...metric)).join('')}</div></article><article class="card glass calendar-card"><div class="card-heading"><div class="label">${icon('calendar')}Rodinný kalendář</div><button class="text-button" data-action="calendar">Vše ${icon('chevron')}</button></div><div class="calendar-date"><div class="date-square"><small>${esc(dayFormat(d,{month:'short'}).replace('.',''))}</small><strong>${d.getDate()}</strong></div><div><strong>${esc(dayFormat(d,{weekday:'long'}))}</strong><p>${list.length?`${list.length} ${list.length<5?'události':'událostí'} v přehledu`:calendarsAvailable()?'Čas jen pro vás':'Kalendář nedostupný'}</p></div></div>${list.slice(0,2).map(e=>eventMarkup(e)).join('')||`<p class="description">${calendarsAvailable()?'Žádné nadcházející události.':'Kalendář zatím není dostupný.'}</p>`}</article>${cameraCard(state.data.cameras[0]||{id:'entrance',name:'Vchod',available:false})}</div>${domesticQuickMarkup()}<div class="section-heading"><h2>Tvoje aplikace</h2><span>Pro společné chvíle i každý den</span></div>${homeAppsMarkup()}<div class="glass home-strip">${homeStrip()}</div>`;}
