function renderCalendar(){const list=events();const days=state.calendarDay?[state.calendarDay]:Array.from({length:7},(_,i)=>{const day=new Date();day.setDate(day.getDate()+i);return HomeTVCalendar.dayKey(day);});const occurrences=calendarOccurrences(list,days),page=paginateTv(occurrences,uiPaging.calendar,4);uiPaging.calendar=page.page;return `<div class="agenda-grid"><article class="card glass agenda-list"><div class="card-heading"><div class="label">${icon('calendar')}Rodinný kalendář</div><button class="text-button" data-calendar-day="all">${state.calendarDay?'Zobrazit všechny dny':'Příštích 7 dnů'}</button></div>${calendarWeek(list)}${isWideTv()?calendarOccurrenceMarkup(page.items):calendarAgenda(list)}${isWideTv()?paginationMarkup('calendar',page):''}</article><article class="card glass"><div class="label">${icon('home')}Rodina na jednom místě</div><p class="description">Společné plány přehledně podle dnů. Vyber datum nahoře nebo zobraz celý týden.</p><div class="chip-row">${state.data.calendars.map(c=>`<span class="chip">${esc(c.name)}</span>`).join('')}</div><p class="description">Události z rodinného kalendáře v HA Domov.</p><button class="small-button" data-action="screensaver">Spustit rodinný spořič</button></article></div>`;}

