function setTab(tab,focus='content'){state.tab=tab;state.lastInput=Date.now();if(focus==='header'){state.appFocusIntent=null;state.menuReturnPending=false;state.appReturnPending=false;}if(isTv&&['home','apps'].includes(tab)){if(focus!=='header')state.appFocusIntent='first';state.pointer=false;if(tab==='apps'){uiPaging.collection='tv';uiPaging.apps=0;}}render();if(isWideTv())window.scrollTo({left:0,top:0,behavior:'instant'});}
