function notify({id,title='Domov',message='',type='info',expiresAt,source,eventType}={}){const notice={id,title,message,type,expiresAt,source,eventType};if(window.NoticePreferences&&!NoticePreferences.allows(notice))return;const key=id||`local-${Date.now()}-${Math.random()}`;let node=$$('.notification').find(n=>n.dataset.noticeId===key);if(!node){node=document.createElement('article');node.dataset.noticeId=key;$('#notifications').append(node);}node.noticePayload=notice;node.className=`notification ${type==='warning'?'warning':''}`;node.innerHTML=`<div class="notice-icon">${icon(type==='warning'?'unlock':'bell')}</div><div><h3>${esc(title)}</h3><p>${esc(message)}</p></div><button class="notice-close" aria-label="Skrýt oznámení">${icon('close')}</button>`;$('.notice-close',node).onclick=()=>removeNotice(key);while($('#notifications').children.length>3)removeNotice($('#notifications').firstElementChild.dataset.noticeId);clearTimeout(noticeTimers.get(key));noticeTimers.set(key,setTimeout(()=>removeNotice(key),Math.min(120000,Math.max(5000,expiresAt?Date.parse(expiresAt)-Date.now():12000))));}
