async function playMedia(url,type='video/mp4',title='Přehrávání'){let parsed;try{parsed=new URL(url,location.href);if(!['http:','https:'].includes(parsed.protocol))throw Error();}catch{return notify({title:'Odkaz nelze otevřít',message:'Použij přímý HTTP nebo HTTPS odkaz na video nebo hudbu.',type:'warning'});}if(type==='image'||type.startsWith('image/')){if(parsed.origin!==location.origin)return notify({title:'Fotografii nelze otevřít',message:'Obrázky přijímáme z místní knihovny.'});showDialog(title,`<img class="camera-large" src="${esc(parsed.href)}" alt="${esc(title)}">`,'camera-dialog');return;}const audio=type==='audio'||type.startsWith('audio/');showDialog(title,`<${audio?'audio':'video'} class="media-player" tabindex="0" controls autoplay playsinline src="${esc(parsed.href)}"></${audio?'audio':'video'}><p class="description">Přímý mediální stream. Podpora kodeku a automatického přehrávání závisí na TV.</p><p class="error-text" id="playback-error"></p>`,'camera-dialog');const media=$('.media-player');media.addEventListener('error',()=>$('#playback-error').textContent='Médium nelze přehrát. Ověř přímý odkaz, dostupnost a podporovaný kodek.');if(type==='hls'||/mpegurl/.test(type)||parsed.pathname.endsWith('.m3u8')){try{await ensureHls();}catch{if($('#playback-error'))$('#playback-error').textContent='HLS přehrávač není dostupný.';return;}if(!media.isConnected)return;media.removeAttribute('src');if(!attachHls(media,parsed.href,()=>{if($('#playback-error'))$('#playback-error').textContent='Stream není podporovaný nebo není dostupný.';}))$('#playback-error').textContent='Tento přehrávač nepodporuje HLS.';}else media.play().catch(()=>{});}
function playUrlDialog(){showDialog('Přehrát médium',`<p>Vlož přímý odkaz na video nebo audio dostupné z televize. Pro soukromé kamery použij přehled kamer.</p><form id="media-form"><label class="form-label" for="media-url">Odkaz na médium</label><div class="form-row"><input id="media-url" class="form-input" type="url" required placeholder="https://server.local/video.mp4"><button class="small-button primary-button" type="submit">Přehrát</button></div><label class="form-label" for="media-type">Typ média</label><select id="media-type"><option value="video/mp4">Video</option><option value="audio/mpeg">Hudba / rádio</option></select></form>`);$('#media-form').onsubmit=e=>{e.preventDefault();playMedia($('#media-url').value,$('#media-type').value);};}
let hlsLoad;function ensureHls(){if(window.Hls)return Promise.resolve();return hlsLoad||=(new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/vendor/hls.light.min.js';script.onload=resolve;script.onerror=()=>{hlsLoad=null;reject(Error('HLS unavailable'));};document.head.append(script);}));}
function attachHls(video,url,onError){if(!isTv&&video.canPlayType('application/vnd.apple.mpegurl')){video.src=url;video.play().catch(()=>{});return true;}if(window.Hls?.isSupported()){state.hls?.destroy();const hls=new window.Hls({enableWorker:false,lowLatencyMode:false,backBufferLength:10,maxBufferLength:12,maxMaxBufferLength:20,liveSyncDuration:12,liveMaxLatencyDuration:30});state.hls=hls;hls.on(window.Hls.Events.ERROR,(_event,data)=>{if(data.fatal){hls.destroy();if(state.hls===hls)state.hls=null;onError();}});hls.loadSource(url);hls.attachMedia(video);hls.on(window.Hls.Events.MANIFEST_PARSED,()=>video.play().catch(()=>{}));return true;}if(video.canPlayType('application/vnd.apple.mpegurl')){video.src=url;video.play().catch(()=>{});return true;}return false;}
const preparedCameras=new Map();
let preparingCamera=null,prepareFocusTimer;
async function prepareCamera(id,quality='smooth'){
  const key=`${id}:${quality}`,cached=preparedCameras.get(key);
  if(cached&&cached.expires>Date.now())return cached.promise;
  if(state.mode!=='live'||!state.bootstrap.authenticated)throw Error('Kamera není připojená.');
  const entry={expires:Date.now()+45000,promise:null};
  entry.promise=(async()=>{
    const r=await fetch(`/api/cameras/${encodeURIComponent(id)}/stream?quality=${quality}`);
    const stream=await r.json();if(!r.ok||!stream.url)throw Error(stream.error||'Stream není dostupný.');
    return stream;
  })().catch(error=>{if(preparedCameras.get(key)===entry)preparedCameras.delete(key);throw error;});
  preparedCameras.set(key,entry);
  while(preparedCameras.size>4)preparedCameras.delete(preparedCameras.keys().next().value);
  return entry.promise;
}
async function prewarmCamera(id){
  if(window.RTCPeerConnection){ensureHls().catch(()=>{});return;}if(preparingCamera||state.dialog||state.saver||document.hidden)return;
  preparingCamera=id;
  try{await ensureHls();const stream=await prepareCamera(id);const r=await fetch(stream.url);if(r.ok)await r.text();}catch{}finally{preparingCamera=null;}
}
function scheduleCameraPreparation(e){const id=e.target.closest('[data-camera]')?.dataset.camera;if(!id)return;clearTimeout(prepareFocusTimer);prepareFocusTimer=setTimeout(()=>prewarmCamera(id),450);}
document.addEventListener('focusin',scheduleCameraPreparation);document.addEventListener('pointerover',scheduleCameraPreparation);
