  showDialog(c.name,`<div class="camera-stage"><video id="camera-video" class="camera-large camera-stream-pending" tabindex="0" controls autoplay playsinline muted></video><img id="camera-snapshot" class="camera-large" src="${snapshot}" alt="Snímek z kamery ${esc(c.name)}"></div><div class="camera-player-footer"><p id="camera-stream-note" class="description">Připravuji živý přenos…</p><div class="camera-quality">${c.hasQualityModes?`<button class="small-button ${quality==='smooth'?'primary-button':''}" data-stream-quality="smooth">Plynulé</button><button class="small-button ${quality==='hd'?'primary-button':''}" data-stream-quality="hd">HD</button>`:''}<button class="small-button hidden" id="camera-retry">Zkusit znovu</button></div></div>`,'camera-dialog');
  state.activeCamera={id,quality};const snapshotController=new AbortController();state.cameraSnapshotController=snapshotController;const requestDialog=$('.dialog'),video=$('#camera-video'),image=$('#camera-snapshot');
  const active=()=>$('.dialog')===requestDialog&&video.isConnected;
  const note=text=>{if(active())$('#camera-stream-note').textContent=text;};
  const fallback=()=>{if(!active())return;video.classList.add('camera-stream-pending');image.classList.remove('hidden');$('#camera-retry').classList.remove('hidden');note('Přenos se přerušil. Zobrazuji snímek.');};
